437		u32 ready;
438	
439		spin_lock(&priv->tx_lock);
440	
441		ready = priv->dmaops->tx_completions(priv);
442	
443		/* Free sent buffers */
444		while (ready && (priv->tx_cons != priv->tx_prod)) {
445			entry = priv->tx_cons % txsize;
446			tx_buff = &priv->tx_ring[entry];
447	
448			if (netif_msg_tx_done(priv))
449				netdev_dbg(priv->dev, "%s: curr %d, dirty %d\n",
450					   __func__, priv->tx_prod, priv->tx_cons);
451	
452			if (likely(tx_buff->skb))
453				priv->dev->stats.tx_packets++;
454	
455			tse_free_tx_buffer(priv, tx_buff);
456			priv->tx_cons++;
457	
458			txcomplete++;
459			ready--;
460		}
461	
462		if (unlikely(netif_queue_stopped(priv->dev) &&
463			     tse_tx_avail(priv) > TSE_TX_THRESH(priv))) {
464			if (netif_queue_stopped(priv->dev) &&
465			    tse_tx_avail(priv) > TSE_TX_THRESH(priv)) {
466				if (netif_msg_tx_done(priv))
467					netdev_dbg(priv->dev, "%s: restart transmit\n",
468						   __func__);
469				netif_wake_queue(priv->dev);
470			}
471		}
472	
473		spin_unlock(&priv->tx_lock);
474		return txcomplete;
475	}
